LayerRow::LayerRow(WeeProcessor&p,int i):name(wee::layerNames[size_t(i)]){
 for(auto*c:std::initializer_list<juce::Component*>{&name,&enabled,&mute,&solo,&lock,&instrument,&volume,&pan,&regenerate,&midi})addAndMakeVisible(c);
 instrument.addItemList(strings(wee::instrumentNames),1);slider(volume);slider(pan);
 enabled.setTooltip("Enable this musical layer");mute.setTooltip("Mute this layer");solo.setTooltip("Hear only enabled solo layers");lock.setTooltip("Preserve this layer's notes during generation");volume.setTooltip("Layer volume");pan.setTooltip("Pan: -1 left, 0 centre, +1 right");name.setTooltip("Select this layer in the piano roll");regenerate.setTooltip("Generate only this layer, preserving the arrangement's harmony");midi.setTooltip("Export this layer's notes, including when muted");
 std::array<juce::ToggleButton*,4>b{&enabled,&mute,&solo,&lock};std::array<const char*,4>ids{"enabled","mute","solo","lock"};for(int n=0;n<4;++n)buttons[size_t(n)]=std::make_unique<BA>(p.params,WeeProcessor::layerId(i,ids[size_t(n)]),*b[size_t(n)]);
 instrumentAttachment=std::make_unique<CA>(p.params,WeeProcessor::layerId(i,"instrument"),instrument);volumeAttachment=std::make_unique<SA>(p.params,WeeProcessor::layerId(i,"volume"),volume);panAttachment=std::make_unique<SA>(p.params,WeeProcessor::layerId(i,"pan"),pan);
}
void LayerRow::resized(){auto r=getLocalBounds().reduced(0,4);name.setBounds(r.removeFromLeft(145).reduced(3,0));enabled.setBounds(r.removeFromLeft(44));mute.setBounds(r.removeFromLeft(38));solo.setBounds(r.removeFromLeft(38));lock.setBounds(r.removeFromLeft(58));instrument.setBounds(r.removeFromLeft(160).reduced(3,0));midi.setBounds(r.removeFromRight(60).reduced(3,0));regenerate.setBounds(r.removeFromRight(80).reduced(3,0));volume.setBounds(r.removeFromLeft(r.getWidth()/2).reduced(3,0));pan.setBounds(r.reduced(3,0));}
WeeEditor::WeeEditor(WeeProcessor& processor):AudioProcessorEditor(processor),p(processor){
 look.setColour(juce::TextButton::buttonColourId,juce::Colour(0xffdbf1fa));look.setColour(juce::TextButton::textColourOffId,juce::Colour(0xff225770));look.setColour(juce::Slider::thumbColourId,juce::Colour(0xff16aee1));look.setColour(juce::ToggleButton::textColourId,juce::Colour(0xff225770));look.setColour(juce::ComboBox::backgroundColourId,juce::Colours::white);look.setColour(juce::ComboBox::textColourId,juce::Colour(0xff225770));setLookAndFeel(&look);
 for(auto*c:std::initializer_list<juce::Component*>{&style,&key,&scale,&bars,&bpm,&volume,&sync,&generate,&play,&save,&drag,&undo,&redo})addAndMakeVisible(c);
 generate.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff14a9de));generate.setColour(juce::TextButton::textColourOffId,juce::Colours::white);
 style.addItemList(strings(wee::styleNames),1);key.addItemList({"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"},1);scale.addItemList({"Minor","Major"},1);bars.addItemList({"8 bars","16 bars"},1);
 aStyle=std::make_unique<CA>(p.params,"style",style);aKey=std::make_unique<CA>(p.params,"key",key);aScale=std::make_unique<CA>(p.params,"scale",scale);aBars=std::make_unique<CA>(p.params,"bars",bars);
 slider(bpm);bpm.setNumDecimalPlacesToDisplay(1);slider(volume);aBpm=std::make_unique<SA>(p.params,"bpm",bpm);aVolume=std::make_unique<SA>(p.params,"gain",volume);aSync=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.params,"sync",sync);
 mixerViewport.setViewedComponent(&mixerContent,false);mixerViewport.setScrollBarsShown(true,true);addAndMakeVisible(mixerViewport);
 for(int i=0;i<8;++i){auto row=std::make_unique<LayerRow>(p,i);row->name.onClick=[this,i]{selectedLayer=i;repaint();};row->regenerate.onClick=[this,i]{compose(i);};row->midi.onClick=[this,i]{exportMidi(false,i);};mixerContent.addAndMakeVisible(*row);rows[size_t(i)]=std::move(row);}
 generate.onClick=[this]{compose();};undo.onClick=[this]{history(false);};redo.onClick=[this]{history(true);};play.onClick=[this]{p.preview=!p.preview.load();};save.onClick=[this]{exportMidi(false);};drag.onFileDrag=[this]{exportMidi(true);};drag.setTooltip("Drag enabled, unmuted/soloed layers as a multitrack MIDI file. SAVE ALL MIDI is the fallback.");
 setResizable(true,true);setResizeLimits(850,650,1600,1250);setSize(1180,960);startTimerHz(20);
}
void WeeEditor::compose(int layer){juce::MemoryBlock before;p.getStateInformation(before);if(layer<0?p.generate():p.regenerateLayer(layer)){past.push_back(std::move(before));if(past.size()>32)past.erase(past.begin());future.clear();}repaint();}
void WeeEditor::history(bool redoAction){auto& from=redoAction?future:past;auto& to=redoAction?past:future;if(from.empty())return;juce::MemoryBlock now;p.getStateInformation(now);to.push_back(std::move(now));p.setStateInformation(from.back().getData(),int(from.back().getSize()));from.pop_back();repaint();}
void WeeEditor::timerCallback(){undo.setEnabled(!past.empty());redo.setEnabled(!future.empty());play.setButtonText(p.preview?"STOP PREVIEW":"PLAY PREVIEW");for(int i=0;i<8;++i){rows[size_t(i)]->regenerate.setEnabled(!rows[size_t(i)]->lock.getToggleState());rows[size_t(i)]->name.setColour(juce::TextButton::buttonColourId,i==selectedLayer?juce::Colour(0xff84d8f5):juce::Colour(0xffdbf1fa));}repaint();}
void WeeEditor::exportMidi(bool dragging,int layer){auto a=p.snapshotArrangement();a.context.bpm=p.tempo.load();std::vector<uint8_t> bytes;
 if(layer>=0){auto c=a.layers[size_t(layer)];c.settings.bpm=a.context.bpm;bytes=wee::midi(c);}else bytes=wee::midi(a,p.audibleLayers());
 if(dragging){auto file=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("WEE-Layers-",".mid");if(file.replaceWithData(bytes.data(),bytes.size()))juce::DragAndDropContainer::performExternalDragDropOfFiles({file.getFullPathName()},false,this);else juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Export failed","Could not create the temporary MIDI file. Use SAVE ALL MIDI.");return;}
 auto filename=layer>=0?juce::String("WEE-")+wee::layerNames[size_t(layer)]+".mid":"WEE-Layers.mid";
 chooser=std::make_unique<juce::FileChooser>("Save MIDI",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile(filename),"*.mid");juce::Component::SafePointer<WeeEditor> safe(this);
 chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[safe,bytes=std::move(bytes)](const juce::FileChooser&fc){if(!safe)return;auto f=fc.getResult();if(f==juce::File{})return;if(!f.withFileExtension("mid").replaceWithData(bytes.data(),bytes.size()))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Export failed","Could not write the MIDI file.");});
}
void WeeEditor::resized(){auto w=getWidth();style.setBounds(26,104,185,34);key.setBounds(222,104,90,34);scale.setBounds(324,104,120,34);bars.setBounds(456,104,115,34);sync.setBounds(w-164,104,145,34);bpm.setBounds(26,164,240,34);volume.setBounds(310,164,240,34);generate.setBounds(w-247,158,220,46);
 int mixerHeight=std::min(384,std::max(140,getHeight()-476));mixerViewport.setBounds(24,246,w-48,mixerHeight);int mixerWidth=std::max(952,mixerViewport.getMaximumVisibleWidth());mixerContent.setSize(mixerWidth,384);
 for(int i=0;i<8;++i)rows[size_t(i)]->setBounds(0,i*48,mixerWidth,48);
 roll={26,float(246+mixerHeight+45),float(w-52),float(getHeight()-(246+mixerHeight+147))};int x=26,y=getHeight()-55,bw=(w-72)/5;for(auto*b:std::initializer_list<juce::Button*>{&play,&save,&drag,&undo,&redo}){b->setBounds(x,y,bw,36);x+=bw+5;}
}
void WeeEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xfff0f5f9));g.setColour(juce::Colours::white);g.fillRoundedRectangle(15,15,float(getWidth()-30),70,22);g.setColour(juce::Colour(0xff14a9dc));g.setFont(juce::FontOptions(42.f));g.drawText("wee",34,20,140,54,juce::Justification::centredLeft);g.setFont(juce::FontOptions(17.f));g.drawText("CREATE + MIXER   /   eight musical layers",195,27,600,40,juce::Justification::centredLeft);g.setColour(juce::Colour(0xff526777));g.setFont(juce::FontOptions(14.f));g.drawText("Preview BPM",28,140,225,24,juce::Justification::centredLeft);g.drawText("Master volume",312,140,230,24,juce::Justification::centredLeft);g.drawText("Layer / select to view           Enabled / Mute / Solo / Lock         Instrument                 Volume                      Pan             Regenerate / MIDI",30,220,getWidth()-60,24,juce::Justification::centredLeft);
 auto a=p.snapshotArrangement();auto& c=a.layers[size_t(selectedLayer)];g.setColour(juce::Colours::white);g.fillRoundedRectangle(roll,12);g.setColour(juce::Colour(0xffdce6ed));for(int i=0;i<=a.context.bars*4;++i){float x=roll.getX()+roll.getWidth()*i/(a.context.bars*4);g.drawVerticalLine(int(x),roll.getY(),roll.getBottom());}
 for(auto&n:c.notes){float x=roll.getX()+float(n.beat/(a.context.bars*4))*roll.getWidth();float y=roll.getBottom()-float(n.pitch-24)/84*roll.getHeight();g.setColour(juce::Colour(0xff1bb0e0));g.fillRoundedRectangle(x,y,std::max(3.f,float(n.length/(a.context.bars*4))*roll.getWidth()),4,1.5f);}
 g.setColour(juce::Colour(0xff526777));g.drawText(juce::String(wee::layerNames[size_t(selectedLayer)])+"  |  "+juce::String(int(c.notes.size()))+" notes  |  Seed "+juce::String(c.settings.seed),28,int(roll.getY())-34,getWidth()-56,28,juce::Justification::centredLeft);
 juce::String status;int code=p.generationStatus.load();if(p.unsupportedMeter)status="Unsupported time signature: WEE requires 4/4";else if(code==1)status="Unlock all layers before changing style, key, scale or loop length. Existing music was preserved.";else if(code==2)status="Layer is locked. Unlock it to regenerate.";else status=juce::String(a.context.bars)+" bars  |  "+juce::String(p.tempo.load(),1)+" BPM  |  Lock preserves notes; enable additional layers with ON. WAV export arrives in Phase 3.";
 g.drawText(status,27,getHeight()-96,getWidth()-54,30,juce::Justification::centredLeft);
}
